// regenerates src/entities.ts from the WHATWG named character reference table.
// CommonMark only recognises the semicolon-terminated forms, so the legacy "&amp" spellings are dropped.
import { mkdir, writeFile } from 'node:fs/promises';

const res = await fetch('https://html.spec.whatwg.org/entities.json');
if (!res.ok) throw new Error(`entities.json: ${res.status}`);
const table = await res.json();

const map = {};
for (const [key, { characters }] of Object.entries(table)) {
	if (key.endsWith(';')) map[key.slice(1, -1)] = characters;
}

const out =
	'// generated by scripts/gen-entities.mjs from https://html.spec.whatwg.org/entities.json - do not edit\n' +
	`export const ENTITIES: Readonly<Record<string, string>> = ${JSON.stringify(map)};\n`;

await mkdir(new URL('../src/', import.meta.url), { recursive: true });
await writeFile(new URL('../src/entities.ts', import.meta.url), out);
console.log(`${Object.keys(map).length} entities`);
